#include <iostream>
#include <fstream>
#include <string>
#include <map>
using namespace std;

int main() {
    ifstream plik("slowa.txt");
    string s;
    map<string, int> cnt;
    while (plik >> s) cnt[s]++;
    cout << "Liczba wystapien kazdego slowa:" << endl;
    string maxS;
    int maxC = 0;
    for (auto& p : cnt) {
        cout << "   " << p.first << ": " << p.second << endl;
        if (p.second > maxC) {
            maxC = p.second;
            maxS = p.first;
        }
    }
    cout << "Najczesciej wystepujace slowo: " << maxS << " (" << maxC << ")" << endl;
    return 0;
}
```

Weryfikacja:
- kot: 4 razy
- pies: 4 razy
- ryba: 2 razy
Remis kot/pies po 4: map iteruje alfabet., kot < pies, wiec kot wygrywa (warunek >)
